package main

import (
	"bufio"
	"fmt"
	"math"
	"os"
	"strconv"
	"strings"
)

func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	var input strings.Builder
	for scanner.Scan() {
		input.WriteString(scanner.Text())
		input.WriteString(" ")
	}
	inp := strings.Fields(input.String())
	if len(inp) < 4 {
		return
	}

	n, _ := strconv.Atoi(inp[0])
	k, _ := strconv.Atoi(inp[1])
	s := inp[2]
	t := inp[3]

	if t[0] == t[1] {
		count := 0
		for _, c := range s {
			if c == rune(t[0]) {
				count++
			}
		}
		x := min(count+k, n)
		fmt.Println(x * (x - 1) / 2)
		return
	}

	// Dimensions: i up to n (access i+1 -> n+1), j up to k (access j+1 -> k+1), cnt0 up to n (access cnt0+1 -> n+1)
	// So size [n+2][k+2][n+2]
	negInf := -1000000000
	f := make([][][]int, n+2)
	for i := range f {
		f[i] = make([][]int, k+2)
		for j := range f[i] {
			f[i][j] = make([]int, n+2)
			for cnt0 := range f[i][j] {
				f[i][j][cnt0] = negInf
			}
		}
	}

	f[0][0][0] = 0

	for i := 0; i <= n; i++ {
		for j := 0; j <= k; j++ {
			for cnt0 := 0; cnt0 <= i; cnt0++ {
				if f[i][j][cnt0] == negInf {
					continue
				}
				cur := f[i][j][cnt0]
				e0 := 0
				if i < len(s) && s[i] == t[0] {
					e0 = 1
				}
				e1 := 0
				if i < len(s) && s[i] == t[1] {
					e1 = 1
				}

				// Keep current char
				f[i+1][j][cnt0+e0] = max(f[i+1][j][cnt0+e0], cur+e1*cnt0)

				// Change to t[0] (cost 1 operation)
				if j+1 <= k {
					f[i+1][j+1][cnt0+1] = max(f[i+1][j+1][cnt0+1], cur)
				}

				// Change to t[1] (cost 1 operation)
				if j+1 <= k {
					f[i+1][j+1][cnt0] = max(f[i+1][j+1][cnt0], cur+cnt0)
				}
			}
		}
	}

	ans := 0
	for i := 0; i <= k; i++ {
		for j := 0; j <= n; j++ {
			ans = max(ans, f[n][i][j])
		}
	}
	fmt.Println(ans)
}

