package main

import (
	"bufio"
	"fmt"
	"math"
	"os"
	"strconv"
	"strings"
)

func forRange(a, b int, fn func(i int) (res interface{}, stop bool)) {
	if a < b {
		for i := a; i <= b; i++ {
			if res, stop := fn(i); stop {
				_ = res
				return
			}
		}
	} else {
		for i := a; i >= b; i-- {
			if res, stop := fn(i); stop {
				_ = res
				return
			}
		}
	}
}

func arrRange(a, b int, fn func(i, prev int) int) []int {
	var p int
	res := make([]int, 0)
	if a < b {
		for i := a; i <= b; i++ {
			if fn != nil {
				p = fn(i, p)
				res = append(res, p)
			} else {
				res = append(res, i)
			}
		}
	} else {
		for i := a; i >= b; i-- {
			if fn != nil {
				p = fn(i, p)
				res = append(res, p)
			} else {
				res = append(res, i)
			}
		}
	}
	return res
}

func sumInts(arr []int, fn func(int) int) int {
	s := 0
	for _, v := range arr {
		if fn != nil {
			s += fn(v)
		} else {
			s += v
		}
	}
	return s
}

func uniqInts(arr []int, fn func(int) int) []int {
	seen := make(map[int]bool)
	res := make([]int, 0)
	for _, v := range arr {
		key := v
		if fn != nil {
			key = fn(v)
		}
		if !seen[key] {
			seen[key] = true
			res = append(res, v)
		}
	}
	return res
}

func minInts(arr []int, fn func(int, int) int) (int, int, int) {
	if len(arr) == 0 {
		return 0, -1, 0
	}
	minVal := math.MaxInt32
	minIdx := -1
	for i, v := range arr {
		val := v
		if fn != nil {
			val = fn(v, i)
		}
		if val < minVal {
			minVal = val
			minIdx = i
		}
	}
	return arr[minIdx], minIdx, minVal
}

func maxInts(arr []int, fn func(int, int) int) (int, int, int) {
	if len(arr) == 0 {
		return 0, -1, 0
	}
	maxVal := math.MinInt32
	maxIdx := -1
	for i, v := range arr {
		val := v
		if fn != nil {
			val = fn(v, i)
		}
		if val > maxVal {
			maxVal = val
			maxIdx = i
		}
	}
	return arr[maxIdx], maxIdx, maxVal
}

func gcd(a, b int) int {
	for b != 0 {
		a, b = b, a%b
	}
	return a
}

func modPow(a, n, m int64) int64 {
	if n == 0 {
		return 1
	}
	if n%2 == 0 {
		return modPow(a*a%m, n/2, m)
	}
	return a * modPow(a, n-1, m) % m
}

func extendedEuclid(a, b int) (int, int) {
	if b == 0 {
		return 1, 0
	}
	x, y := extendedEuclid(b, a%b)
	return y, x - (a/b)*y
}

