			}
		}
	}
	f[0][0][0] = 0

	for i := 0; i < n; i++ {
		for j := 0; j <= k; j++ {
			for cnt0 := 0; cnt0 <= i; cnt0++ {
				if f[i][j][cnt0] == NEG_INF {
