				}
				e1 := 0
				if s[i] == t[1] {
					e1 = 1
				}

				// keep char
				ncnt0 := cnt0 + e0
				if f[i+1][j][ncnt0] < cur + e1*cnt0 {
					f[i+1][j][ncnt0] = cur + e1*cnt0
				}

				// change to t[0]
				if j+1 <= k {
					if f[i+1][j+1][cnt0+1] < cur {
